const SLOT_NAMES = ['helmet', 'torso', 'pants', 'hands', 'feet', 'weapon', 'offhand', 'wings'];

export function splitGarments(meshes) {
  for (const mesh of [...meshes]) {
      if (!mesh.name.startsWith('equip_torso_') || !mesh.getTotalVertices()) continue;
      const positions=mesh.getVerticesData('position'),indices=mesh.getIndices();
      const top=[],bottom=[];
      for(let i=0;i<indices.length;i+=3){
        const y=(positions[indices[i]*3+1]+positions[indices[i+1]*3+1]+positions[indices[i+2]*3+1])/3;
        (y<.78?bottom:top).push(indices[i],indices[i+1],indices[i+2]);
      }
      if(top.length&&bottom.length){
        const pants=mesh.clone(mesh.name.replace('equip_torso_','equip_pants_'),mesh.parent,true);
        pants.makeGeometryUnique();pants.setIndices(bottom);meshes.push(pants);
        mesh.makeGeometryUnique();mesh.setIndices(top);
      }
    }
}

