          mat.diffuseTexture=this.texture(p.textures[0]);mat.diffuseTexture.hasAlpha=true;mat.useAlphaFromDiffuseTexture=true;mesh.material=mat;
          if (p.billType===1||p.billType===3)mesh.billboardMode=Mesh.BILLBOARDMODE_ALL;
